package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

func isVowel(c byte) bool {
	return c == 'A' || c == 'E' || c == 'O' || c == 'U' || c == 'Y' || c == 'I'
}

func main() {
	reader := bufio.NewReader(os.Stdin)
	str, _ := reader.ReadString('\n')
	str = strings.TrimSuffix(str, "\n")
	str = strings.TrimSuffix(str, "\r")

	s := " " + str + " "
	jumpSize := 1
	pos := 0

	for {
		next := pos + 1
		for next < len(s) && s[next] != ' ' && !isVowel(s[next]) {
			next++
		}
		if next-pos > jumpSize {
			jumpSize = next - pos
		}
		pos = next
		if s[pos] == ' ' {
			break
		}
	}

	fmt.Println(jumpSize)
}

